import{_ as a,o as e,c as d,a2 as s}from"./chunks/framework.BZO4qERu.js";const b=JSON.parse('{"title":"魔法","description":"","frontmatter":{},"headers":[],"relativePath":"guide/skills-magic.md","filePath":"guide/skills-magic.md","lastUpdated":1791998216000}'),n={name:"guide/skills-magic.md"};function r(o,t,i,l,c,p){return e(),d("div",null,[...t[0]||(t[0]=[s(`<h1 id="魔法" tabindex="-1">魔法 <a class="header-anchor" href="#魔法" aria-label="Permalink to &quot;魔法&quot;">​</a></h1><p>释放魔法会消耗<strong>魔法值</strong>。魔法通常来源于角色装备的<strong>魔法卡包</strong>，但部分角色也可能初始就自带魔法。</p><blockquote><p>魔法卡包是魔法技能的主要来源，其标准实现见 <a href="./prefabricated-entities.html">预制实体 - 魔法卡包</a>。</p></blockquote><h2 id="魔法流程" tabindex="-1">魔法流程 <a class="header-anchor" href="#魔法流程" aria-label="Permalink to &quot;魔法流程&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>行动回合 → 选择魔法 → 选择目标 → 开始吟唱 → 结束回合</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>时间流逝 → 吟唱等待时间归零 → 轮到施法者的结算回合</span></span>
<span class="line"><span>   ↓</span></span>
<span class="line"><span>释放成功 → 结算动作硬直与奖励 → 等待下一次行动</span></span>
<span class="line"><span>释放失败 → 计失败尝试硬直 → 按剩余预算和状态重新决策</span></span></code></pre></div><p>开始吟唱时检查魔法值，结算回合重新检查并在释放时扣除。吟唱结算是独立的正常回合，会触发回合开始/结束、发放与回收奖励、增加行动回合计数。处于吟唱态时直接处理释放，不选择新的主动动作；释放失败或提前被打断后可以按正常规则继续决策。</p><p>结算回合不补充决策点。普通魔法保留发起回合的行动计数与已用配额，先行动再吟唱的硬直按正常多行动规则在释放回合聚合。协同魔法的预算和原队列位置规则见<a href="./chain-action.html">协同行动</a>。</p><h2 id="吟唱终止" tabindex="-1">吟唱终止 <a class="header-anchor" href="#吟唱终止" aria-label="Permalink to &quot;吟唱终止&quot;">​</a></h2><p><code>r</code> 是剩余吟唱时间，<code>c</code> 是失败补偿，默认 3，可通过 <code>CastFailureHardnessTime</code> 配置。</p><table tabindex="0"><thead><tr><th>情况</th><th>普通魔法的处理</th></tr></thead><tbody><tr><td>在他人回合或时间流逝中被技能打断</td><td>取消施法，保持剩余等待时间 <code>r</code></td></tr><tr><td>在他人回合丢失全部目标</td><td>取消施法，等待时间为 <code>min(r,c)</code></td></tr><tr><td>没有角色正在行动时丢失全部目标</td><td>取消施法，保持 <code>r</code>，不应用补偿上限</td></tr><tr><td>在自己的结算回合资源不足、无有效目标或释放前被打断</td><td>失败尝试计 <code>c</code>，随后按剩余 DP、配额及控制状态继续决策</td></tr><tr><td>被预释放爆发技覆盖</td><td>取消原吟唱，按预释放规则设置位置，不另加失败补偿</td></tr><tr><td>死亡或移出队列</td><td>清施法状态与待释放技能，回收顺延奖励；重新加入或复活不恢复旧施法</td></tr></tbody></table><p>只丢失部分目标时继续吟唱。非指向性魔法在保留目标格且允许空地施法时也可以继续。终止吟唱会立即重算控制状态，有控制效果的角色不会被强行变成可行动。</p><p>失败不返还已支付的决策点，也不额外扣失败费用；资源不足的释放尝试不扣 MP。失败尝试的 <code>c</code> 参与本回合硬直聚合，即使后续成功动作的硬直为 0 也不会抹掉该补偿；成功释放 0 硬直魔法本身不触发补偿。</p><p>所有施法终止都会回收已顺延的被动奖励。失败与打断记录归施法者，预释放覆盖或移出仅记录取消原因。</p><h2 id="等级" tabindex="-1">等级 <a class="header-anchor" href="#等级" aria-label="Permalink to &quot;等级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>初始</th><th>最高</th><th>升级方式</th></tr></thead><tbody><tr><td>角色自带</td><td>1 级</td><td>8 级</td><td>等级解锁 (8/16/24/32/40/48/56)</td></tr><tr><td>魔法卡包</td><td>卡包决定</td><td>—</td><td>魔法卡升级（没有等级要求）</td></tr></tbody></table><hr><h2 id="魔法瓶颈" tabindex="-1">魔法瓶颈 <a class="header-anchor" href="#魔法瓶颈" aria-label="Permalink to &quot;魔法瓶颈&quot;">​</a></h2><p>部分魔法技能可能对角色的<strong>智力</strong>具有要求，我们称之为<strong>魔法瓶颈</strong>。</p><h2 id="魔法效能" tabindex="-1">魔法效能 <a class="header-anchor" href="#魔法效能" aria-label="Permalink to &quot;魔法效能&quot;">​</a></h2><p><code>魔法效能</code> 是一个表示魔法技能<strong>实际施展效果被放大或缩小</strong>的系数关系：以<strong>魔法瓶颈为基准线</strong>，角色智力减去魔法瓶颈的<strong>差值的正负</strong>决定了实际施展效果。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>魔法效能 = 1.0 + (角色智力 - 魔法瓶颈) ÷ 魔法瓶颈</span></span></code></pre></div><table tabindex="0"><thead><tr><th>智力 vs 瓶颈</th><th>魔法效能</th><th>实际效果</th></tr></thead><tbody><tr><td>智力 = 瓶颈</td><td>100%</td><td>标准效果</td></tr><tr><td>智力 &lt; 瓶颈</td><td>&lt; 100%（最低可降至 1%）</td><td>效果被削弱</td></tr><tr><td>智力 &gt; 瓶颈</td><td>&gt; 100%（至多可提升至 200%）</td><td>效果获得增强</td></tr></tbody></table>`,22)])])}const g=a(n,[["render",r]]);export{b as __pageData,g as default};
